describe('orders consumer', () => {
  it('enriches valid orders and commits offset', async () => {
    const mockCtx = {
      message: {
        key: Buffer.from('order-123'),
        value: Buffer.from(JSON.stringify({
          orderId: 'order-123',
          customerId: 'cust-456',
          total: 99.99
        })),
        partition: 0,
        offset: 42n
      },
      emit: jest.fn().mockResolvedValue(undefined),
      commit: jest.fn().mockResolvedValue(undefined)
    };

    await onMessage(mockCtx);

    expect(mockCtx.emit).toHaveBeenCalledWith(
      'orders_enriched',
      expect.any(Buffer),
      expect.stringContaining('processedAt')
    );
    expect(mockCtx.commit).toHaveBeenCalled();
  });

  it('publishes to DLQ on validation failure', async () => {
    const mockCtx = {
      message: {
        key: Buffer.from('order-123'),
        value: Buffer.from(JSON.stringify({ orderId: 'order-123' })),
        partition: 0,
        offset: 42n
      },
      emit: jest.fn().mockResolvedValue(undefined),
      commit: jest.fn().mockResolvedValue(undefined)
    };

    await onMessage(mockCtx);

    expect(mockCtx.emit).toHaveBeenCalledWith(
      'dead_letter',
      expect.any(Buffer),
      expect.stringContaining('missing required fields')
    );
    expect(mockCtx.commit).toHaveBeenCalled();
  });
});
